INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77e-4a20-7a72-9313-8026d7faa4f5'::uuid, '019f9df7-a2a2-7877-afdf-c436930f3059'::uuid, 'Linear equations and inequalities', 'Solve inequalities like equations, but reverse the inequality sign when multiplying or dividing by a negative.', ARRAY['Do the same operation to both sides', 'Adding/subtracting, or multiplying/dividing by a positive, keeps the inequality sign', 'Multiplying or dividing by a negative flips the inequality sign', 'On a number line: hollow circle for < or >; filled circle for <= or >=']::text[], ARRAY['{"note":"Dividing by -2 flips < to >.","label":"Sign reversal rule","expression":"If -2q < 10 then q > 5"}'::jsonb]::text[], ARRAY['{"steps":["Multiply both sides by 6: 3(2x + 1) >= 2(5 - 4x)","6x + 3 >= 10 - 8x","14x >= 7, so x >= 1/2"],"answer":"x >= 1/2","question":"Solve (2x + 1)/2 >= (5 - 4x)/3."}'::jsonb, '{"steps":["Multiply both sides by -4 and flip the sign","x <= -48"],"answer":"x <= -48","question":"Solve (-1/4)x >= 12."}'::jsonb]::text[], ARRAY['{"fix":"Reverse the sign whenever you multiply or divide by a negative number.","mistake":"Keeping the inequality sign the same after dividing by a negative."}'::jsonb, '{"fix":"Hollow circle means excluded (< or >); filled means included (<= or >=).","mistake":"Using a filled circle for a strict inequality on a number line."}'::jsonb]::text[], ARRAY['After solving, test one value from your range to confirm it works.', 'Compound inequalities like 10 < x <= 20 mean both ends apply at once.']::text[], ARRAY['t04']::text[], 601, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:51:39.424Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77e-4a20-7c37-92ed-92b483c805c2'::uuid, '019f9df7-a2a2-7877-afdf-c436930f3059'::uuid, 'Simultaneous and quadratic equations', 'Two unknowns need two equations (elimination or substitution). Quadratics need factorising, the formula, or completing the square, and context may reject some roots.', ARRAY['Elimination when coefficients can be matched; substitution when one variable is already isolated', 'A quadratic must be in the form ax^2 + bx + c = 0 before solving', 'In applications, reject roots that are impossible (e.g. negative rates or distances)']::text[], ARRAY['{"note":"For ax^2 + bx + c = 0 with a != 0.","label":"Quadratic formula","expression":"x = (-b +/- sqrt(b^2 - 4ac)) / 2a"}'::jsonb]::text[], ARRAY['{"steps":["Multiply first equation by 3: 6x - 15y = -3","Subtract from second: (-4y) - (-15y) = 30 - (-3) => 11y = 33 => y = 3","Substitute: 2x - 15 = -1 => 2x = 14 => x = 7"],"answer":"x = 7, y = 3","question":"Solve 2x - 5y = -1 and 6x - 4y = 30 by elimination."}'::jsonb, '{"steps":["x = (30 +/- sqrt(900 + 60000)) / 6","x = 46.13 or x = -36.13","Reject the negative rate"],"answer":"x = 46.13 (reject -36.13)","question":"Solve 3x^2 - 30x - 5000 = 0 to 2 d.p. (pump rate; reject impossible roots)."}'::jsonb]::text[], ARRAY['{"fix":"Move every term to one side so the equation reads ... = 0 first.","mistake":"Trying to factorise a quadratic that has not been rearranged to equal zero."}'::jsonb, '{"fix":"State both roots, then reject any that fail the context check.","mistake":"Giving only one solution to a quadratic."}'::jsonb]::text[], ARRAY['If answers are needed to 2 decimal places, use the quadratic formula.', 'Substitute both answers back into an original equation to check.']::text[], ARRAY['t05']::text[], 602, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:51:39.424Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77f-0ed2-7580-a556-eae0ff73494a'::uuid, '019f9df7-a2a2-7888-aef2-fd58477eb864'::uuid, 'Set notation and Venn diagrams', 'Sets group elements. Read the symbols carefully, then shade the matching region on a Venn diagram.', ARRAY['Intersection (A intersect B) is elements in both; union (A union B) is elements in either', 'A'' is the complement: elements of the universal set not in A', 'A intersect B = empty set means the sets are disjoint (no overlap)', 'n(A) is the number of elements in A']::text[], ARRAY['{"note":"Subtract the overlap so it is not counted twice.","label":"Union count","expression":"n(A union B) = n(A) + n(B) - n(A intersect B)"}'::jsonb, '{"note":"Universal set is often written as epsilon.","label":"Complement","expression":"A'' = universal set minus A"}'::jsonb]::text[], ARRAY['{"steps":["A intersect B = {4, 5}","B'' = {1,2,3,10}; A intersect B'' = {2,3}","(A intersect B'')'' is everything except {2,3}, i.e. {1,4,5,6,7,8,9,10}"],"answer":"A intersect B = {4,5}; shaded region is all except A-only","question":"With dummy sets epsilon = {1..10}, A = {2,3,4,5}, B = {4,5,6,7,8,9}, list A intersect B and describe (A intersect B'')''."}'::jsonb]::text[], ARRAY['{"fix":"Elements in both sets would be counted twice. Subtract the intersection.","mistake":"Adding n(A) and n(B) without subtracting the overlap."}'::jsonb, '{"fix":"Union looks like a cup and collects everything; intersection is the overlap only.","mistake":"Confusing the union and intersection symbols."}'::jsonb]::text[], ARRAY['For shading questions, invent temporary dummy elements, shade, then erase them.', 'Fill the intersection of a Venn diagram first, then work outwards.']::text[], ARRAY['t17']::text[], 701, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:52:29.778Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77f-0ed2-76b8-9b76-1055b754a2df'::uuid, '019f9df7-a2a2-7899-9f80-1aed5da88c11'::uuid, 'Matrix operations and applications', 'Matrices store data in rows and columns. Addition needs matching order; multiplication needs the columns of the first to equal the rows of the second.', ARRAY['Order is rows x columns; a square matrix has equal rows and columns', 'Add/subtract entry by entry only when orders match; scalar multiplies every entry', 'For AB, columns of A must equal rows of B; result has order (rows of A) x (columns of B)', 'AB is usually not the same as BA']::text[], ARRAY['{"note":"Always state rows first.","label":"Order of a matrix","expression":"order = rows x columns"}'::jsonb, '{"note":"Inner numbers must match.","label":"Multiplication dimensions","expression":"(m x n) x (n x p) = (m x p)"}'::jsonb]::text[], ARRAY['{"steps":["(5 6 2 / 8 4 0) times (0.20 / 1.50 / 0.40)","Andy: 5(0.20)+6(1.50)+2(0.40) = 10.80","Mark: 8(0.20)+4(1.50)+0(0.40) = 7.60"],"answer":"(10.80 / 7.60); totals spent by Andy and Mark","question":"Andy buys 5 pencils, 6 pens, 2 erasers; Mark buys 8, 4, 0. Costs are $0.20, $1.50, $0.40. Form matrices and find each total spend."}'::jsonb]::text[], ARRAY['{"fix":"Multiply each row of the first by each column of the second, then add.","mistake":"Multiplying matrices element by element."}'::jsonb, '{"fix":"Matrix multiplication is not commutative. Keep the given order.","mistake":"Assuming AB equals BA."}'::jsonb]::text[], ARRAY['Write the dimensions above each matrix before multiplying to check it is possible.', 'For interpretation questions, state what a row and a column represent in context.']::text[], ARRAY['t04']::text[], 801, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:52:29.778Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77f-0ed2-76dd-afbc-7cc39778b1b2'::uuid, '019f9df7-a2a2-78ab-b1d6-52be9d287151'::uuid, 'Angle properties in lines and triangles', 'Almost every angle question uses one of a small set of named rules, and you must quote the rule to get the reason mark.', ARRAY['Angles on a straight line add to 180 degrees', 'Angles around a point add to 360 degrees', 'Vertically opposite angles are equal']::text[], ARRAY['{"note":"True for every triangle.","label":"Angle sum of a triangle","expression":"a + b + c = 180 degrees"}'::jsonb, '{"note":"Saves a step in many problems.","label":"Exterior angle of a triangle","expression":"exterior = sum of the two opposite interior angles"}'::jsonb]::text[], ARRAY['{"steps":["Third interior angle = 180 - 47 - 68 = 65","Exterior angle = 180 - 65 = 115","Check: 47 + 68 = 115, matching the exterior angle rule"],"answer":"115 degrees","question":"In a triangle, two angles are 47 and 68 degrees. Find the exterior angle at the third vertex."}'::jsonb]::text[], ARRAY['{"fix":"Name the rule, for example angles on a straight line, to earn the reason mark.","mistake":"Giving an answer with no reason stated."}'::jsonb, '{"fix":"Only use equal sides or angles that are marked or given.","mistake":"Assuming a triangle is isosceles because it looks like it."}'::jsonb]::text[], ARRAY['Mark every angle you calculate on the diagram as you go.', 'Diagrams are often not to scale, so never measure with a ruler.']::text[], ARRAY['t11']::text[], 901, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:52:29.778Z'::timestamptz) ON CONFLICT (id) DO NOTHING;